// DB row → app object (camelCase). Also used by db.js for rows from Supabase.
export function fromRow(r) {
  return {
    id: r.id,
    name: r.name,
    category: r.category,
    type: r.type,
    minLevel: r.min_level,
    maxLevel: r.max_level,
    intensity: r.intensity,
    players: r.players,
    equipment: r.equipment,
    summary: r.summary,
    setup: r.setup,
    steps: r.steps ?? [],
    coachingPoints: r.coaching_points ?? [],
    commonMistakes: r.common_mistakes ?? [],
    levelNotes: r.level_notes ?? {},
    successTarget: r.success_target,
    diagram: r.diagram,
    imageUrl: r.image_url,
    videoUrl: r.video_url,
    sources: r.sources ?? [],
    groupNotes: r.group_notes ?? {},
  };
}

export const DRILLS = DRILL_ROWS.map(fromRow);
